export function SkeletonLoading({
  loaded = {{loaded}},
  shape = "{{shape}}",
  accent = "{{accent}}",
}) {
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#241430aa" }}>
      {!loaded && (
        <>
          <div aria-hidden="true">
            <span style={{ display: "block", width: shape === "card" ? "100%" : 44, height: shape === "card" ? 60 : 44, borderRadius: shape === "card" ? 8 : 999, background: "#24143014", marginBottom: 10 }} />
            <span style={{ display: "block", height: 11, background: "#24143014", borderRadius: 6, marginBottom: 8, width: "100%" }} />
            <span style={{ display: "block", height: 11, background: "#24143014", borderRadius: 6, marginBottom: 8, width: "55%" }} />
          </div>
          <p role="status" aria-live="polite">Loading profile&hellip;</p>
        </>
      )}
      {loaded && (
        <div style={{ display: "flex", flexDirection: "column", alignItems: "flex-start", gap: 2 }}>
          <span style={{ width: 44, height: 44, borderRadius: 999, marginBottom: 8, background: accent }} />
          <strong>Amara Cole</strong>
          <p style={{ margin: 0, color: "#241430aa", fontSize: 12 }}>Product designer</p>
        </div>
      )}
    </div>
  );
}
